import heapq
import math

def solve(x, y, k):
    queue = [(0, x, 0, 0)]
    visited = set()
    while queue:
        dist, curr_x, time, step = heapq.heappop(queue)
        if (curr_x, curr_y) == (y, x):
            return time
        if (curr_x, curr_y) in visited:
            continue
        visited.add((curr_x, curr_y))
        if curr_x > 0 and curr_x + 1 <= 100 and dist + 1 + k + math.ceil((curr_x + 1 - x) / 2) <= 100:
            heapq.heappush(queue, (dist + 1 + k + math.ceil((curr_x + 1 - x) / 2), curr_x - 1, time + 1, step + 1))
        if curr_y > 0 and curr_y + 1 <= 100 and dist + 1 + k + math.ceil((curr_y - y) / 2) <= 100:
            heapq.heappush(queue, (dist + 1 + k + math.ceil((curr_y - y) / 2), curr_y - 1, time + 1, step + 1))
        if curr_y < 100 and curr_y + 1 <= 100 and dist + 1 + k + math.ceil((curr_y - y) / 2) <= 100:
            heapq.heappush(queue, (dist + 1 + k + math.ceil((curr_y - y) / 2), curr_y + 1, time + 1, step + 1))

