def solve(x, y, k):
    if x == y:
        return 0
    if x > y:
        x, y = y, x
    if k == 0:
        return float('inf')
    if k == 1:
        return 2 * (x + y)
    if x + y <= k:
        return x + y
    else:
        return x + y + 1 + min(solve(x + k, y, k - (x + y)), solve(x - 1, y, k))

