import sys

def solve():
    n = int(input())
    health = list(map(int, input().split()))

    min_cost = float('inf')

    def dfs(i, cost, memo):
        nonlocal min_cost
        if i == n:
            return 0

        if (i, cost) in memo:
            return memo[(i, cost)]

        if health[i] == 0:
            return cost + 1

        min_cost = min(min_cost, cost + 1 + dfs(i + 1, cost + 1, memo))

        if health[i] > 0:
            if health[i] <= 2:
                min_cost = min(min_cost, cost + 1 + dfs(i + 1, cost, memo))
            else:
                min_cost = min(min_cost, cost + 1 + dfs(i + 1, cost + health[i] // 2, memo))

        return memo[(i, cost)]

    for i in range(n):
        memo = {}
        min_cost = dfs(0, 0, memo)

    print(min_cost)

