        if len(p) < len(q):
            return False
        for i in range(len(p)):
            if p[i]!= q[i]:
                return False
        return True

    def is_common_suffix(p, q):
        if len(p) < len(q):
            return False
        for i in range(len(q) - 1, -1, -1):
            if p[i]!= q[i]:
                return False
        return True

