def solve(n):
    def is_valid(a, b, c):
        return a!= b and a!= c and b!= c

    def is_permutation(a, b, c):
        return a == b and b == c

    def backtrack(start, path, current):
        if len(path) == n:
            result.append(path[:])
            return
        if start == n:
            result.append(path[:])
            return
        for i in range(start, n):
            if is_permutation(path, i, current):
                backtrack(i + 1, path + [i], current + [i])

    result = []
    backtrack(1, [], [1])
    return result

