def solve(n):
    def is_valid_permutation(p):
        for i in range(1, n):
            if abs(p[i] - p[i-1] - 1) > 1 or abs(p[i] - p[i+1] - 1) > 1:
                return False
        return True

    def get_permutations(arr):
        if len(arr) == 1:
            return [arr]
        result = []
        for i in range(len(arr)):
            first_part = get_permutations(arr[:i] + [arr[i]+1] + arr[i+1:])
            second_part = get_permutations(arr[:i] + [arr[i]-1] + arr[i+1:])
            for p in first_part + second_part:
                result.append(p)
        return result

    if n == 2:
        if is_valid_permutation([1, 2]):
            return [1, 2]
        else:
            return -1

    return get_permutations(list(range(1, n))

