def solve(n):
    def generate_permutation(arr, i, j):
        if i == j:
            return arr
        else:
            for k in range(i + 1, j + 1):
                arr[i], arr[k] = arr[k], arr[i]
                yield generate_permutation(arr, i + 1, j)
                arr[i], arr[k] = arr[k], arr[i]

    arr = list(range(1, n + 1))
    max_val = 0
    for i in generate_permutation(arr, 0, n - 1):
        if i > max_val:
            max_val = i
    print(' '.join(str(x) for x in max_val + list(reversed(solve(n - max_val))))
